#include "Hashes.h"

// ---------------------------------------------------------------------------
// Hex helpers
// ---------------------------------------------------------------------------
static const char kHexUpperDigits[] = "0123456789ABCDEF";
static const char kHexLowerDigits[] = "0123456789abcdef";

static std::string HexImpl(const Byte* data, size_t size, const char* digits) {
  std::string s;
  s.resize(size * 2);
  for (size_t i = 0; i < size; i++) {
    s[i * 2] = digits[data[i] >> 4];
    s[i * 2 + 1] = digits[data[i] & 15];
  }
  return s;
}

std::string HexUpper(const Byte* data, size_t size) { return HexImpl(data, size, kHexUpperDigits); }
std::string HexLower(const Byte* data, size_t size) { return HexImpl(data, size, kHexLowerDigits); }

// ---------------------------------------------------------------------------
// CRC32 (poly 0xEDB88320, reflected, init/final xor 0xFFFFFFFF)
// ---------------------------------------------------------------------------
namespace {

class CRC32Hasher : public Hasher {
public:
  CRC32Hasher() { Init(); }
  void Init() { _crc = 0xFFFFFFFFu; }
  void Update(const Byte* data, size_t size) override {
    uint32_t c = _crc;
    for (size_t i = 0; i < size; i++)
      c = kTable[(c ^ data[i]) & 0xFF] ^ (c >> 8);
    _crc = c;
  }
  size_t DigestSize() const override { return 4; }
  void Final(Byte* out) override {
    uint32_t v = _crc ^ 0xFFFFFFFFu;
    out[0] = (Byte)(v >> 24);
    out[1] = (Byte)(v >> 16);
    out[2] = (Byte)(v >> 8);
    out[3] = (Byte)v;
  }
  uint32_t Value() const { return _crc ^ 0xFFFFFFFFu; }

private:
  uint32_t _crc;
  static uint32_t kTable[256];
  static struct TableInit {
    TableInit() {
      for (uint32_t i = 0; i < 256; i++) {
        uint32_t c = i;
        for (int k = 0; k < 8; k++)
          c = (c >> 1) ^ ((c & 1) ? 0xEDB88320u : 0);
        kTable[i] = c;
      }
    }
  } kInit;
};

uint32_t CRC32Hasher::kTable[256];
CRC32Hasher::TableInit CRC32Hasher::kInit;

// ---------------------------------------------------------------------------
// CRC64 (poly 0xC96C5795D7870F42, reflected, init/final xor all-ones) CRC-64/XZ
// ---------------------------------------------------------------------------
class CRC64Hasher : public Hasher {
public:
  CRC64Hasher() { _crc = 0xFFFFFFFFFFFFFFFFULL; }
  void Update(const Byte* data, size_t size) override {
    uint64_t c = _crc;
    for (size_t i = 0; i < size; i++)
      c = kTable[(c ^ data[i]) & 0xFF] ^ (c >> 8);
    _crc = c;
  }
  size_t DigestSize() const override { return 8; }
  void Final(Byte* out) override {
    uint64_t v = _crc ^ 0xFFFFFFFFFFFFFFFFULL;
    for (int i = 0; i < 8; i++) out[i] = (Byte)(v >> (56 - 8 * i));
  }

private:
  uint64_t _crc;
  static uint64_t kTable[256];
  static struct TableInit {
    TableInit() {
      for (uint64_t i = 0; i < 256; i++) {
        uint64_t c = i;
        for (int k = 0; k < 8; k++)
          c = (c >> 1) ^ ((c & 1) ? 0xC96C5795D7870F42ULL : 0);
        kTable[i] = c;
      }
    }
  } kInit;
};

