// ---------------------------------------------------------------------------
// SHA1
// ---------------------------------------------------------------------------
static inline uint32_t RotL32(uint32_t v, int n) { return (v << n) | (v >> (32 - n)); }

class SHA1Hasher : public Hasher {
public:
  SHA1Hasher() { Reset(); }
  void Reset() {
    _h[0] = 0x67452301u; _h[1] = 0xEFCDAB89u; _h[2] = 0x98BADCFEu;
    _h[3] = 0x10325476u; _h[4] = 0xC3D2E1F0u;
    _len = 0;
    _bufLen = 0;
  }
  void Update(const Byte* data, size_t size) override {
    _len += size;
    while (size > 0) {
      size_t take = 64 - _bufLen;
      if (take > size) take = size;
      memcpy(_buf + _bufLen, data, take);
      _bufLen += take;
      data += take;
      size -= take;
      if (_bufLen == 64) {
        ProcessBlock(_buf);
        _bufLen = 0;
      }
    }
  }
  size_t DigestSize() const override { return 20; }
  void Final(Byte* out) override {
    uint64_t bitLen = (uint64_t)_len * 8;
    Byte pad = 0x80;
    Update(&pad, 1);
    Byte zero = 0;
    while (_bufLen != 56) Update(&zero, 1);
    Byte lenBytes[8];
    for (int i = 0; i < 8; i++) lenBytes[i] = (Byte)(bitLen >> (56 - 8 * i));
    Update(lenBytes, 8);
    for (int i = 0; i < 5; i++) {
      out[i * 4] = (Byte)(_h[i] >> 24);
      out[i * 4 + 1] = (Byte)(_h[i] >> 16);
      out[i * 4 + 2] = (Byte)(_h[i] >> 8);
      out[i * 4 + 3] = (Byte)_h[i];
    }
    Reset();
  }

private:
  void ProcessBlock(const Byte* p) {
    uint32_t w[80];
    for (int i = 0; i < 16; i++)
      w[i] = ((uint32_t)p[i * 4] << 24) | ((uint32_t)p[i * 4 + 1] << 16) |
             ((uint32_t)p[i * 4 + 2] << 8) | (uint32_t)p[i * 4 + 3];
    for (int i = 16; i < 80; i++)
      w[i] = RotL32(w[i - 3] ^ w[i - 8] ^ w[i - 14] ^ w[i - 16], 1);
    uint32_t a = _h[0], b = _h[1], c = _h[2], d = _h[3], e = _h[4];
    for (int i = 0; i < 80; i++) {
      uint32_t f, k;
      if (i < 20) { f = (b & c) | ((~b) & d); k = 0x5A827999u; }
      else if (i < 40) { f = b ^ c ^ d; k = 0x6ED9EBA1u; }
      else if (i < 60) { f = (b & c) | (b & d) | (c & d); k = 0x8F1BBCDCu; }
      else { f = b ^ c ^ d; k = 0xCA62C1D6u; }
      uint32_t t = RotL32(a, 5) + f + e + k + w[i];
      e = d; d = c; c = RotL32(b, 30); b = a; a = t;
    }
    _h[0] += a; _h[1] += b; _h[2] += c; _h[3] += d; _h[4] += e;
  }

  uint32_t _h[5];
  uint64_t _len;
  Byte _buf[64];
  size_t _bufLen;
};

