class SHA256Hasher : public Hasher {
public:
  SHA256Hasher() { Reset(); }
  void Reset() {
    _h[0] = 0x6a09e667u; _h[1] = 0xbb67ae85u; _h[2] = 0x3c6ef372u; _h[3] = 0xa54ff53au;
    _h[4] = 0x510e527fu; _h[5] = 0x9b05688cu; _h[6] = 0x1f83d9abu; _h[7] = 0x5be0cd19u;
    _len = 0;
    _bufLen = 0;
  }
  void Update(const Byte* data, size_t size) override {
    _len += size;
    while (size > 0) {
      size_t take = 64 - _bufLen;
      if (take > size) take = size;
      memcpy(_buf + _bufLen, data, take);
      _bufLen += take;
      data += take;
      size -= take;
      if (_bufLen == 64) {
        ProcessBlock(_buf);
        _bufLen = 0;
      }
    }
  }
  size_t DigestSize() const override { return 32; }
  void Final(Byte* out) override {
    uint64_t bitLen = (uint64_t)_len * 8;
    Byte pad = 0x80;
    Update(&pad, 1);
    Byte zero = 0;
    while (_bufLen != 56) Update(&zero, 1);
    Byte lenBytes[8];
    for (int i = 0; i < 8; i++) lenBytes[i] = (Byte)(bitLen >> (56 - 8 * i));
    Update(lenBytes, 8);
    for (int i = 0; i < 8; i++) {
      out[i * 4] = (Byte)(_h[i] >> 24);
      out[i * 4 + 1] = (Byte)(_h[i] >> 16);
      out[i * 4 + 2] = (Byte)(_h[i] >> 8);
      out[i * 4 + 3] = (Byte)_h[i];
    }
    Reset();
  }

private:
  void ProcessBlock(const Byte* p) {
    uint32_t w[64];
    for (int i = 0; i < 16; i++)
      w[i] = ((uint32_t)p[i * 4] << 24) | ((uint32_t)p[i * 4 + 1] << 16) |
             ((uint32_t)p[i * 4 + 2] << 8) | (uint32_t)p[i * 4 + 3];
    for (int i = 16; i < 64; i++) {
      uint32_t s0 = RotL32(w[i - 15], 7) ^ RotL32(w[i - 15], 18) ^ (w[i - 15] >> 3);
      uint32_t s1 = RotL32(w[i - 2], 17) ^ RotL32(w[i - 2], 19) ^ (w[i - 2] >> 10);
      w[i] = w[i - 16] + s0 + w[i - 7] + s1;
    }
    uint32_t a = _h[0], b = _h[1], c = _h[2], d = _h[3];
    uint32_t e = _h[4], f = _h[5], g = _h[6], h = _h[7];
    for (int i = 0; i < 64; i++) {
      uint32_t S1 = RotL32(e, 6) ^ RotL32(e, 11) ^ RotL32(e, 25);
      uint32_t ch = (e & f) ^ ((~e) & g);
      uint32_t t1 = h + S1 + ch + kSHA256K[i] + w[i];
      uint32_t S0 = RotL32(a, 2) ^ RotL32(a, 13) ^ RotL32(a, 22);
      uint32_t maj = (a & b) ^ (a & c) ^ (b & c);
      uint32_t t2 = S0 + maj;
      h = g; g = f; f = e; e = d + t1;
      d = c; c = b; b = a; a = t1 + t2;
    }
    _h[0] += a; _h[1] += b; _h[2] += c; _h[3] += d;
    _h[4] += e; _h[5] += f; _h[6] += g; _h[7] += h;
  }

  uint32_t _h[8];
  uint64_t _len;
  Byte _buf[64];
  size_t _bufLen;
};

// ---------------------------------------------------------------------------
// XXH64 (seed 0)
// ---------------------------------------------------------------------------
static const uint64_t kXXP1 = 11400714785074694791ULL;
static const uint64_t kXXP2 = 14029467366897019727ULL;
static const uint64_t kXXP3 = 1609587929392839161ULL;
static const uint64_t kXXP4 = 9650029242287828579ULL;
static const uint64_t kXXP5 = 2870177450012600261ULL;

static inline uint64_t RotL64(uint64_t v, int n) { return (v << n) | (v >> (64 - n)); }
static inline uint64_t XXRound(uint64_t acc, uint64_t lane) {
  acc += lane * kXXP2;
  acc = RotL64(acc, 31);
  acc *= kXXP1;
  return acc;
}
static inline uint64_t XXMergeRound(uint64_t acc, uint64_t val) {
  val = XXRound(0, val);
  acc ^= val;
  acc = acc * kXXP1 + kXXP4;
  return acc;
}
static inline uint64_t XXGet64(const Byte* p) {
  uint64_t v = 0;
  for (int i = 7; i >= 0; i--) v = (v << 8) | p[i];
  return v;
}
static inline uint32_t XXGet32(const Byte* p) {
  return (uint32_t)p[0] | ((uint32_t)p[1] << 8) | ((uint32_t)p[2] << 16) | ((uint32_t)p[3] << 24);
}
static inline uint64_t XXAvalanche(uint64_t h) {
  h ^= h >> 33;
  h *= kXXP2;
  h ^= h >> 29;
  h *= kXXP3;
  h ^= h >> 32;
  return h;
}

class XXH64Hasher : public Hasher {
public:
  XXH64Hasher() {
    _v[0] = kXXP1 + kXXP2;
    _v[1] = kXXP2;
    _v[2] = 0;
    _v[3] = 0 - kXXP1;
    _total = 0;
    _bufLen = 0;
  }
  void Update(const Byte* data, size_t size) override {
    _total += size;
    // fill buffer to a 32-byte stripe first
    if (_bufLen > 0) {
      size_t take = 32 - _bufLen;
      if (take > size) take = size;
      memcpy(_buf + _bufLen, data, take);
      _bufLen += take;
      data += take;
      size -= take;
      if (_bufLen == 32) {
        ProcessStripe(_buf);
        _bufLen = 0;
      }
    }
    while (size >= 32) {
      ProcessStripe(data);
      data += 32;
      size -= 32;
    }
    if (size > 0) {
      memcpy(_buf, data, size);
      _bufLen = size;
    }
  }
  size_t DigestSize() const override { return 8; }
  void Final(Byte* out) override {
    uint64_t h;
    if (_total >= 32) {
      h = RotL64(_v[0], 1) + RotL64(_v[1], 7) + RotL64(_v[2], 12) + RotL64(_v[3], 18);
      h = XXMergeRound(h, _v[0]);
      h = XXMergeRound(h, _v[1]);
      h = XXMergeRound(h, _v[2]);
      h = XXMergeRound(h, _v[3]);
    } else {
      h = kXXP5; // seed 0 + kXXP5
    }
    h += _total;
    const Byte* p = _buf;
    size_t rem = _bufLen;
    while (rem >= 8) {
      h ^= XXRound(0, XXGet64(p));
      h = RotL64(h, 27) * kXXP1 + kXXP4;
      p += 8;
      rem -= 8;
    }
    if (rem >= 4) {
      h ^= (uint64_t)XXGet32(p) * kXXP1;
      h = RotL64(h, 23) * kXXP2 + kXXP3;
      p += 4;
      rem -= 4;
    }
    while (rem > 0) {
      h ^= (uint64_t)(*p) * kXXP5;
      h = RotL64(h, 11) * kXXP1;
      p++;
      rem--;
    }
    h = XXAvalanche(h);
    for (int i = 0; i < 8; i++) out[i] = (Byte)(h >> (56 - 8 * i));
  }

private:
  void ProcessStripe(const Byte* p) {
    _v[0] = XXRound(_v[0], XXGet64(p));
    _v[1] = XXRound(_v[1], XXGet64(p + 8));
    _v[2] = XXRound(_v[2], XXGet64(p + 16));
    _v[3] = XXRound(_v[3], XXGet64(p + 24));
  }

  uint64_t _v[4];
  uint64_t _total;
  Byte _buf[32];
  size_t _bufLen;
};

