// ---------------------------------------------------------------------------
// One-shot helpers
// ---------------------------------------------------------------------------
static std::string OneShotHex(Hasher* h, const Byte* d, size_t n, bool upper) {
  h->Update(d, n);
  ByteBuf digest(h->DigestSize());
  h->Final(digest.data());
  std::string s = upper ? HexUpper(digest.data(), digest.size())
                        : HexLower(digest.data(), digest.size());
  delete h;
  return s;
}

std::string CRC32Hex(const Byte* d, size_t n) { return OneShotHex(CreateCRC32(), d, n, true); }
std::string CRC64Hex(const Byte* d, size_t n) { return OneShotHex(CreateCRC64(), d, n, true); }
std::string SHA256Hex(const Byte* d, size_t n) { return OneShotHex(CreateSHA256(), d, n, false); }
std::string SHA1Hex(const Byte* d, size_t n) { return OneShotHex(CreateSHA1(), d, n, false); }
std::string XXH64Hex(const Byte* d, size_t n) { return OneShotHex(CreateXXH64(), d, n, true); }

uint32_t CRC32Value(const Byte* d, size_t n) {
  CRC32Hasher h;
  h.Update(d, n);
  return h.Value();
}

#include "Aes.h"
#include "Hashes.h"

// ---------------------------------------------------------------------------
// AES-256 block cipher, from scratch.
// S-box / inverse S-box are generated at static-init time from the GF(2^8)
// multiplicative inverse (poly 0x11B) and the AES affine transform.
// ---------------------------------------------------------------------------
namespace {

Byte gSBox[256];
Byte gInvSBox[256];
Byte gRcon[15];

static Byte GFMul(Byte a, Byte b) {
  Byte r = 0;
  while (b) {
    if (b & 1) r ^= a;
    Byte hi = a & 0x80;
    a <<= 1;
    if (hi) a ^= 0x1B;
    b >>= 1;
  }
  return r;
}

static Byte GFPow(Byte a, int e) {
  Byte r = 1;
  while (e > 0) {
    if (e & 1) r = GFMul(r, a);
    a = GFMul(a, a);
    e >>= 1;
  }
  return r;
}

static inline Byte RotL8(Byte v, int n) { return (Byte)((v << n) | (v >> (8 - n))); }

struct AesTablesInit {
  AesTablesInit() {
    for (int i = 0; i < 256; i++) {
      Byte inv = (i == 0) ? 0 : GFPow((Byte)i, 254); // a^-1 = a^254
      Byte s = (Byte)(inv ^ RotL8(inv, 1) ^ RotL8(inv, 2) ^ RotL8(inv, 3) ^ RotL8(inv, 4) ^ 0x63);
      gSBox[i] = s;
      gInvSBox[s] = (Byte)i;
    }
    Byte c = 1;
    for (int i = 1; i < 15; i++) {
      gRcon[i] = c;
      c = GFMul(c, 2);
    }
  }
};
static AesTablesInit gAesInit;

// AES-256: Nk = 8, Nr = 14, expanded key = 240 bytes.
struct Aes256Ctx {
  Byte rk[240]; // 15 round keys of 16 bytes
};

static void Aes256ExpandKey(const Byte key[32], Aes256Ctx& ctx) {
  memcpy(ctx.rk, key, 32);
  int bytesDone = 32;
  Byte t[4] = { ctx.rk[28], ctx.rk[29], ctx.rk[30], ctx.rk[31] };
  int rconIdx = 1;
  while (bytesDone < 240) {
    if (bytesDone % 32 == 0) {
      // RotWord + SubWord + Rcon
      Byte tmp = t[0];
      t[0] = (Byte)(gSBox[t[1]] ^ gRcon[rconIdx++]);
      t[1] = gSBox[t[2]];
      t[2] = gSBox[t[3]];
      t[3] = gSBox[tmp];
    } else if (bytesDone % 32 == 16) {
      // SubWord only (AES-256 special case)
      for (int i = 0; i < 4; i++) t[i] = gSBox[t[i]];
    }
    for (int i = 0; i < 4; i++) {
      Byte v = (Byte)(ctx.rk[bytesDone - 32] ^ t[i]);
      ctx.rk[bytesDone++] = v;
      t[i] = v;
    }
  }
}

static void AddRoundKey(Byte* s, const Byte* rk) {
  for (int i = 0; i < 16; i++) s[i] ^= rk[i];
}

// state is column-major: s[4*c + r]
static void SubBytes(Byte* s) {
  for (int i = 0; i < 16; i++) s[i] = gSBox[s[i]];
}
static void InvSubBytes(Byte* s) {
  for (int i = 0; i < 16; i++) s[i] = gInvSBox[s[i]];
}

static void ShiftRows(Byte* s) {
  Byte t[16];
  for (int r = 0; r < 4; r++)
    for (int c = 0; c < 4; c++)
      t[4 * c + r] = s[4 * ((c + r) % 4) + r];
  memcpy(s, t, 16);
}
static void InvShiftRows(Byte* s) {
  Byte t[16];
  for (int r = 0; r < 4; r++)
    for (int c = 0; c < 4; c++)
      t[4 * c + r] = s[4 * ((c - r + 4) % 4) + r];
  memcpy(s, t, 16);
}

static void MixColumns(Byte* s) {
  for (int c = 0; c < 4; c++) {
    Byte* col = s + 4 * c;
    Byte a0 = col[0], a1 = col[1], a2 = col[2], a3 = col[3];
    col[0] = (Byte)(GFMul(a0, 2) ^ GFMul(a1, 3) ^ a2 ^ a3);
    col[1] = (Byte)(a0 ^ GFMul(a1, 2) ^ GFMul(a2, 3) ^ a3);
    col[2] = (Byte)(a0 ^ a1 ^ GFMul(a2, 2) ^ GFMul(a3, 3));
    col[3] = (Byte)(GFMul(a0, 3) ^ a1 ^ a2 ^ GFMul(a3, 2));
  }
}
static void InvMixColumns(Byte* s) {
  for (int c = 0; c < 4; c++) {
    Byte* col = s + 4 * c;
    Byte a0 = col[0], a1 = col[1], a2 = col[2], a3 = col[3];
    col[0] = (Byte)(GFMul(a0, 14) ^ GFMul(a1, 11) ^ GFMul(a2, 13) ^ GFMul(a3, 9));
    col[1] = (Byte)(GFMul(a0, 9) ^ GFMul(a1, 14) ^ GFMul(a2, 11) ^ GFMul(a3, 13));
    col[2] = (Byte)(GFMul(a0, 13) ^ GFMul(a1, 9) ^ GFMul(a2, 14) ^ GFMul(a3, 11));
    col[3] = (Byte)(GFMul(a0, 11) ^ GFMul(a1, 13) ^ GFMul(a2, 9) ^ GFMul(a3, 14));
  }
}

static void Aes256EncryptBlock(const Aes256Ctx& ctx, const Byte in[16], Byte out[16]) {
  Byte s[16];
  memcpy(s, in, 16);
  AddRoundKey(s, ctx.rk);
  for (int round = 1; round < 14; round++) {
    SubBytes(s);
    ShiftRows(s);
    MixColumns(s);
    AddRoundKey(s, ctx.rk + 16 * round);
  }
  SubBytes(s);
  ShiftRows(s);
  AddRoundKey(s, ctx.rk + 16 * 14);
  memcpy(out, s, 16);
}

static void Aes256DecryptBlock(const Aes256Ctx& ctx, const Byte in[16], Byte out[16]) {
  Byte s[16];
  memcpy(s, in, 16);
  AddRoundKey(s, ctx.rk + 16 * 14);
  for (int round = 13; round >= 1; round--) {
    InvShiftRows(s);
    InvSubBytes(s);
    AddRoundKey(s, ctx.rk + 16 * round);
    InvMixColumns(s);
  }
  InvShiftRows(s);
  InvSubBytes(s);
  AddRoundKey(s, ctx.rk);
  memcpy(out, s, 16);
}

// Convert password (UTF-8 from the console) to UTF-16LE bytes.
static void PasswordToUtf16Le(const std::string& password, ByteBuf& out) {
  out.clear();
  size_t i = 0;
  while (i < password.size()) {
    uint32_t cp;
    unsigned char c = (unsigned char)password[i];
    if (c < 0x80) {
      cp = c;
      i += 1;
    } else if ((c & 0xE0) == 0xC0 && i + 1 < password.size()) {
      cp = ((c & 0x1F) << 6) | ((unsigned char)password[i + 1] & 0x3F);
      i += 2;
    } else if ((c & 0xF0) == 0xE0 && i + 2 < password.size()) {
      cp = ((c & 0x0F) << 12) | (((unsigned char)password[i + 1] & 0x3F) << 6) |
           ((unsigned char)password[i + 2] & 0x3F);
      i += 3;
    } else if ((c & 0xF8) == 0xF0 && i + 3 < password.size()) {
      cp = ((c & 0x07) << 18) | (((unsigned char)password[i + 1] & 0x3F) << 12) |
           (((unsigned char)password[i + 2] & 0x3F) << 6) |
           ((unsigned char)password[i + 3] & 0x3F);
      i += 4;
    } else {
      cp = c; // invalid UTF-8: pass byte through
      i += 1;
    }
    if (cp > 0xFFFF) {
      // encode as surrogate pair
      cp -= 0x10000;
      uint16_t hi = (uint16_t)(0xD800 + (cp >> 10));
      uint16_t lo = (uint16_t)(0xDC00 + (cp & 0x3FF));
      out.push_back((Byte)hi); out.push_back((Byte)(hi >> 8));
      out.push_back((Byte)lo); out.push_back((Byte)(lo >> 8));
    } else {
      out.push_back((Byte)cp);
      out.push_back((Byte)(cp >> 8));
    }
  }
}

} // anonymous namespace

// ---------------------------------------------------------------------------
// AES-256 CBC single-shot helpers
// ---------------------------------------------------------------------------
void Aes256CbcEncrypt(const Byte key[32], const Byte iv[16], const Byte* in, Byte* out, size_t size) {
  Aes256Ctx ctx;
  Aes256ExpandKey(key, ctx);
  Byte prev[16];
  memcpy(prev, iv, 16);
  for (size_t off = 0; off < size; off += 16) {
    Byte block[16];
    for (int i = 0; i < 16; i++) block[i] = (Byte)(in[off + i] ^ prev[i]);
    Aes256EncryptBlock(ctx, block, out + off);
    memcpy(prev, out + off, 16);
  }
}

void Aes256CbcDecrypt(const Byte key[32], const Byte iv[16], const Byte* in, Byte* out, size_t size) {
  Aes256Ctx ctx;
  Aes256ExpandKey(key, ctx);
  Byte prev[16];
  memcpy(prev, iv, 16);
  for (size_t off = 0; off < size; off += 16) {
    Byte block[16];
    Aes256DecryptBlock(ctx, in + off, block);
    for (int i = 0; i < 16; i++) out[off + i] = (Byte)(block[i] ^ prev[i]);
    memcpy(prev, in + off, 16);
  }
}

// ---------------------------------------------------------------------------
// 7z AES key derivation (method 06 F1 07 01)
// ---------------------------------------------------------------------------
// Derive key from (salt, password, numCyclesPower): SHA256 updated 2^cycles
// times, each update with (salt || password_utf16le || counter32le).
void SevenZipKeyFromPassword(uint32_t numCyclesPower, const Byte* salt, size_t saltSize,
                             const std::string& password, Byte key[32]) {
  ByteBuf pw;
  PasswordToUtf16Le(password, pw);

  ByteBuf buf;
  buf.reserve(saltSize + pw.size() + 4);
  if (saltSize > 0) buf.insert(buf.end(), salt, salt + saltSize);
  buf.insert(buf.end(), pw.begin(), pw.end());
  size_t baseLen = buf.size();
  buf.resize(baseLen + 4); // room for counter

  Hasher* sha = CreateSHA256();
  uint64_t rounds = (uint64_t)1 << numCyclesPower;
  for (uint64_t i = 0; i < rounds; i++) {
    Set32(buf.data() + baseLen, (uint32_t)i);
    sha->Update(buf.data(), buf.size());
  }
  sha->Final(key);
  delete sha;
}

// Parse props blob:
//   b0: bits 0..5 = NumCyclesPower (0x3F = special), bit 6 = ivSize present,
//       bit 7 = saltSize present
//   b1: high nibble = saltSize - 1 (when present), low nibble = ivSize - 1
//   then saltSize salt bytes, then ivSize iv bytes.
bool SevenZipDeriveKey(const Byte* props, size_t propsSize, const std::string& password,
                       Byte key[32], Byte iv[16], uint32_t* numCyclesPowerOut) {
  if (propsSize < 2) return false;
  Byte b0 = props[0];
  Byte b1 = props[1];
  uint32_t numCyclesPower = b0 & 0x3F;
  size_t saltSize = ((b0 >> 7) & 1) + (b1 >> 4);
  size_t ivSize = ((b0 >> 6) & 1) + (b1 & 0x0F);
  if (2 + saltSize + ivSize > propsSize) return false;
  const Byte* salt = props + 2;
  const Byte* ivBytes = props + 2 + saltSize;

  memset(iv, 0, 16);
  size_t ivCopy = ivSize < 16 ? ivSize : 16;
  if (ivCopy > 0) memcpy(iv, ivBytes, ivCopy);

  if (numCyclesPowerOut) *numCyclesPowerOut = numCyclesPower;

  memset(key, 0, 32);
  if (numCyclesPower == 0x3F) {
    // Special case: key material is stored directly in salt, iv in iv bytes.
    size_t keySize = saltSize < 32 ? saltSize : 32;
    if (keySize > 0) memcpy(key, salt, keySize);
    return true;
  }
  SevenZipKeyFromPassword(numCyclesPower, salt, saltSize, password, key);
  return true;
}

ByteBuf SevenZipMakeProps(uint32_t numCyclesPower, const Byte* salt, size_t saltSize,
                          const Byte* iv, size_t ivSize) {
  if (numCyclesPower > 0x3F) numCyclesPower = 0x3F;
  if (saltSize > 16) saltSize = 16;
  if (ivSize > 16) ivSize = 16;
  Byte b0 = (Byte)(numCyclesPower & 0x3F);
  Byte b1 = 0;
  if (saltSize > 0) {
    b0 |= 0x80;
    b1 |= (Byte)((saltSize - 1) << 4);
  }
  if (ivSize > 0) {
    b0 |= 0x40;
    b1 |= (Byte)(ivSize - 1);
  }
  ByteBuf props;
  props.push_back(b0);
  props.push_back(b1);
  if (saltSize > 0) props.insert(props.end(), salt, salt + saltSize);
  if (ivSize > 0) props.insert(props.end(), iv, iv + ivSize);
  return props;
}

#include "../src/Hashes.h"
#include "../src/Aes.h"
#include <cstdio>
#include <cstring>

static int failures = 0;
static void check(const char* name, const std::string& got, const std::string& want) {
  bool ok = got == want;
  printf("%-40s %s  got=%s want=%s\n", name, ok ? "OK  " : "FAIL", got.c_str(), want.c_str());
  if (!ok) failures++;
}
static void checkBool(const char* name, bool ok) {
  printf("%-40s %s\n", name, ok ? "OK  " : "FAIL");
  if (!ok) failures++;
}

int main() {
  const char* msg = "Hello, 7-Zip!\n";
  const Byte* d = (const Byte*)msg;
  size_t n = strlen(msg);

  // --- one-shot helpers ---
  check("CRC32", CRC32Hex(d, n), "A08EE65D");
  check("CRC64", CRC64Hex(d, n), "D9C894775CB93995");
  check("SHA1", SHA1Hex(d, n), "f6f8e4201e4e6742deda9ff33dd72ac4fb7926cb");
  check("SHA256", SHA256Hex(d, n), "fd4621a1113e12bff69f43f9410426401d656f9d55040d273dc30dc3d75e98e3");
  check("XXH64", XXH64Hex(d, n), "9C20A6847EAE9824");

  // --- well-known vectors ---
  const char* abc = "abc";
  check("CRC32(abc)", CRC32Hex((const Byte*)abc, 3), "352441C2");
  check("SHA1(abc)", SHA1Hex((const Byte*)abc, 3), "a9993e364706816aba3e25717850c26c9cd0d89d");
  check("SHA256(abc)", SHA256Hex((const Byte*)abc, 3),
        "ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad");
  check("XXH64(empty)", XXH64Hex((const Byte*)"", 0), "EF46DB3751D8E999");
  check("CRC64(123456789)", CRC64Hex((const Byte*)"123456789", 9), "995DC9BBDF1939FA"); // CRC-64/XZ check value
  check("CRC32Value(abc)", CRC32Value((const Byte*)abc, 3) == 0x352441C2u ? "match" : "mismatch", "match");

  // --- streaming in odd-sized chunks must equal one-shot ---
  {
    std::string big;
    for (int i = 0; i < 10000; i++) big += "The quick brown fox jumps over the lazy dog. ";
    struct { Hasher* (*mk)(); bool upper; } specs[] = {
      {CreateCRC32, true}, {CreateCRC64, true}, {CreateSHA1, false}, {CreateSHA256, false}, {CreateXXH64, true}
    };
    const char* names[] = {"CRC32", "CRC64", "SHA1", "SHA256", "XXH64"};
    for (int s = 0; s < 5; s++) {
      Hasher* h = specs[s].mk();
      h->Update((const Byte*)big.data(), big.size());
      ByteBuf one(h->DigestSize());
      h->Final(one.data());
      std::string oneHex = specs[s].upper ? HexUpper(one.data(), one.size()) : HexLower(one.data(), one.size());
      delete h;

      h = specs[s].mk();
      size_t pos = 0;
      size_t chunk = 1;
      while (pos < big.size()) {
        size_t take = chunk;
        if (take > big.size() - pos) take = big.size() - pos;
        h->Update((const Byte*)big.data() + pos, take);
        pos += take;
        chunk = chunk * 7 + 3; // irregular chunk sizes: 1,10,73,514,...
      }
      ByteBuf two(h->DigestSize());
      h->Final(two.data());
      std::string twoHex = specs[s].upper ? HexUpper(two.data(), two.size()) : HexLower(two.data(), two.size());
      delete h;
      char nm[64];
      snprintf(nm, sizeof nm, "streaming==oneshot %s", names[s]);
      check(nm, twoHex, oneHex);
    }
  }

  // --- AES-256 known answer (FIPS-197 style, NIST vector) ---
  {
    Byte key[32], plain[16], cipher[16], back[16];
    for (int i = 0; i < 32; i++) key[i] = (Byte)i;
    for (int i = 0; i < 16; i++) plain[i] = (Byte)(0x00 + 0x11 * i);
    Byte zeroIv[16] = {0};
    Aes256CbcEncrypt(key, zeroIv, plain, cipher, 16); // CBC with zero iv on 1 block == ECB
    static const Byte expect[16] = {0x8e,0xa2,0xb7,0xca,0x51,0x67,0x45,0xbf,0xea,0xfc,0x49,0x90,0x4b,0x49,0x60,0x89};
    check("AES-256 KAT", HexLower(cipher, 16), HexLower(expect, 16));
    Aes256CbcDecrypt(key, zeroIv, cipher, back, 16);
    checkBool("AES-256 decrypt KAT", memcmp(back, plain, 16) == 0);
  }

  // --- CBC roundtrip multi-block, in-place-safe separate buffers ---
  {
    Byte key[32], iv[16];
    for (int i = 0; i < 32; i++) key[i] = (Byte)(i * 3 + 1);
    for (int i = 0; i < 16; i++) iv[i] = (Byte)(i * 5 + 2);
    ByteBuf plain(16 * 37);
    for (size_t i = 0; i < plain.size(); i++) plain[i] = (Byte)(i * 7 + i / 3);
    ByteBuf cipher(plain.size()), back(plain.size());
    Aes256CbcEncrypt(key, iv, plain.data(), cipher.data(), plain.size());
    Aes256CbcDecrypt(key, iv, cipher.data(), back.data(), back.size());
    checkBool("AES-256-CBC roundtrip 592B", back == plain);
    checkBool("AES-256-CBC differs", cipher != plain);
  }

  // --- 7z key derivation + padded roundtrip ---
  {
    std::string password = "Secret#42";
    Byte salt[8] = {0x11, 0x22, 0x33, 0x44, 0x55, 0x66, 0x77, 0x88};
    Byte ivIn[16];
    for (int i = 0; i < 16; i++) ivIn[i] = (Byte)(0xA0 + i);
    uint32_t cycles = 19;

    ByteBuf props = SevenZipMakeProps(cycles, salt, sizeof salt, ivIn, sizeof ivIn);
    checkBool("props size", props.size() == 2 + 8 + 16);

    Byte key1[32], key2[32], iv1[16], iv2[16];
    uint32_t cyclesOut = 0;
    bool ok = SevenZipDeriveKey(props.data(), props.size(), password, key1, iv1, &cyclesOut);
    checkBool("DeriveKey ok", ok);
    checkBool("cycles parsed", cyclesOut == cycles);
    checkBool("iv parsed", memcmp(iv1, ivIn, 16) == 0);
    SevenZipKeyFromPassword(cycles, salt, sizeof salt, password, key2);
    checkBool("DeriveKey==KeyFromPassword", memcmp(key1, key2, 32) == 0);

    // wrong password must give different key
    Byte key3[32], iv3[16];
    SevenZipDeriveKey(props.data(), props.size(), "Secret#43", key3, iv3, nullptr);
    checkBool("wrong pw -> different key", memcmp(key1, key3, 32) != 0);

    // encrypt/decrypt with zero-padding to 16 (7z style)
    ByteBuf plain(200);
    for (size_t i = 0; i < plain.size(); i++) plain[i] = (Byte)(i * 13 + 5);
    size_t padded = (plain.size() + 15) & ~(size_t)15;
    ByteBuf buf = plain;
    buf.resize(padded, 0);
    ByteBuf cipher(padded), back(padded);
    Aes256CbcEncrypt(key1, iv1, buf.data(), cipher.data(), padded);
    Aes256CbcDecrypt(key1, iv1, cipher.data(), back.data(), padded);
    back.resize(plain.size());
    checkBool("7zAES padded roundtrip", back == plain);
  }

  // --- edge cases: no salt, no iv, cycles 0; malformed props ---
  {
    Byte key[32], iv[16];
    ByteBuf props = SevenZipMakeProps(0, nullptr, 0, nullptr, 0);
    checkBool("minimal props size", props.size() == 2 && props[0] == 0 && props[1] == 0);
    bool ok = SevenZipDeriveKey(props.data(), props.size(), "pw", key, iv, nullptr);
    checkBool("derive cycles=0 ok", ok);
    // cycles=0: single SHA256 over (utf16le(pw) || 00000000)
    Hasher* sha = CreateSHA256();
    Byte expect[32];
    Byte pwBytes[4] = {'p', 0, 'w', 0};
    Byte ctr[4] = {0, 0, 0, 0};
    sha->Update(pwBytes, 4);
    sha->Update(ctr, 4);
    sha->Final(expect);
    delete sha;
    checkBool("cycles=0 == single SHA256", memcmp(key, expect, 32) == 0);
    checkBool("derive malformed (empty) fails", !SevenZipDeriveKey(nullptr, 0, "pw", key, iv, nullptr));
    Byte oneByte[1] = {0x00};
    checkBool("derive malformed (1 byte) fails", !SevenZipDeriveKey(oneByte, 1, "pw", key, iv, nullptr));
    Byte truncated[2] = {0xC0, 0xFF}; // claims 16+16 salt/iv, but no data
    checkBool("derive truncated fails", !SevenZipDeriveKey(truncated, 2, "pw", key, iv, nullptr));
  }

  // --- cycles=0x3F edge: key directly from salt ---
  {
    Byte props[2 + 20 + 4];
    props[0] = 0x3F | 0x80 | 0x40; // cycles=0x3F, salt&iv present
    props[1] = (Byte)(((16 - 1) << 4) | (4 - 1)); // salt 16, iv 4 -> wait, saltSize=1+(b1>>4)
    // saltSize = 1 + (b1>>4) = 16, ivSize = 1 + (b1&0xF) = 4
    for (int i = 0; i < 20; i++) props[2 + i] = (Byte)(0x30 + i);
    for (int i = 0; i < 4; i++) props[2 + 20 + i] = (Byte)(0xE0 + i);
    Byte key[32], iv[16];
    uint32_t cyc = 0;
    bool ok = SevenZipDeriveKey(props, sizeof props, "ignored", key, iv, &cyc);
    checkBool("0x3F derive ok", ok && cyc == 0x3F);
    checkBool("0x3F key from salt", memcmp(key, props + 2, 16) == 0);
    Byte ivWant[16] = {0};
    memcpy(ivWant, props + 22, 4);
    checkBool("0x3F iv", memcmp(iv, ivWant, 16) == 0);
  }

  printf(failures ? "\n%d FAILURES\n" : "\nALL TESTS PASSED\n", failures);
  return failures ? 1 : 0;
}

