// End-to-end verification: decrypt a real 7zAES (Copy method) archive produced
// by the reference binary, using only src/Aes.cpp (+ src/Hashes.cpp).
#include "Aes.h"
#include "Hashes.h"
#include <cstdio>
#include <cstring>

static ByteBuf g;
static size_t pos;

static uint64_t ReadUVarint() {
  Byte first = g[pos++];
  if (first < 0x80) return first;
  uint64_t value = 0;
  Byte mask = 0x80;
  int i;
  for (i = 0; i < 8; i++) {
    if ((first & mask) == 0) break;
    value = (value << 8) | g[pos++];
    mask >>= 1;
  }
  return value | ((uint64_t)(first & (mask - 1)) << (8 * i));
}

int main(int argc, char** argv) {
  if (argc < 4) { printf("usage: %s archive password plainfile\n", argv[0]); return 1; }
  if (!ReadWholeFile(argv[1], g)) { printf("cannot read archive\n"); return 1; }
  ByteBuf plain;
  if (!ReadWholeFile(argv[3], plain)) { printf("cannot read plainfile\n"); return 1; }

  // signature header
  if (g.size() < 32 || memcmp(g.data(), "7z\xBC\xAF\x27\x1C", 6) != 0) { printf("bad sig\n"); return 1; }
  uint64_t nextOff = Get64(g.data() + 12);
  uint64_t nextSize = Get64(g.data() + 20);
  pos = 32 + nextOff;
  size_t headerEnd = pos + nextSize;

  ByteBuf aesProps;
  uint64_t packPos = 0, packSize = 0, unpackSize = 0;
  bool foundAes = false;

  if (g[pos++] != 0x01) { printf("expected kHeader (encrypted headers unsupported here)\n"); return 1; }
  while (pos < headerEnd) {
    Byte id = g[pos++];
    if (id == 0x00) break; // kEnd
    if (id == 0x04) { // kMainStreamsInfo
      while (true) {
        Byte sid = g[pos++];
        if (sid == 0x00) break;
        if (sid == 0x06) { // kPackInfo
          packPos = ReadUVarint();
          uint64_t numPack = ReadUVarint();
          while (true) {
            Byte pid = g[pos++];
            if (pid == 0x00) break;
            if (pid == 0x09) { // kSize
              for (uint64_t i = 0; i < numPack; i++) packSize = ReadUVarint();
            } else if (pid == 0x0A) { // kCRC
              uint64_t allAreDefined = g[pos++];
              if (allAreDefined) pos += 4 * numPack;
              else { printf("crc bitmap unsupported\n"); return 1; }
            } else { printf("unknown packinfo id %02x\n", pid); return 1; }
          }
        } else if (sid == 0x07) { // kUnpackInfo
          if (g[pos++] != 0x0B) { printf("expected kFolder\n"); return 1; }
          uint64_t numFolders = ReadUVarint();
          Byte external = g[pos++];
          if (external != 0 || numFolders != 1) { printf("unexpected folders\n"); return 1; }
          uint64_t numCoders = ReadUVarint();
          uint64_t totIn = 0, totOut = 0;
          for (uint64_t c = 0; c < numCoders; c++) {
            Byte flags = g[pos++];
            int idSize = flags & 0x0F;
            ByteBuf cid(g.begin() + pos, g.begin() + pos + idSize);
            pos += idSize;
            uint64_t nin = 1, nout = 1;
            if (flags & 0x10) { nin = ReadUVarint(); nout = ReadUVarint(); }
            totIn += nin; totOut += nout;
            if (flags & 0x20) {
              uint64_t ps = ReadUVarint();
              if (cid.size() == 4 && cid[0] == 0x06 && cid[1] == 0xF1 && cid[2] == 0x07 && cid[3] == 0x01) {
                aesProps.assign(g.begin() + pos, g.begin() + pos + ps);
                foundAes = true;
              }
              pos += ps;
            }
            printf("coder id=%s\n", HexUpper(cid.data(), cid.size()).c_str());
          }
          for (uint64_t i = 1; i < totOut; i++) { ReadUVarint(); ReadUVarint(); } // bind pairs
          uint64_t numPackStreams = totIn - (totOut - 1);
          if (numPackStreams != 1) { ReadUVarint(); }
          if (g[pos++] != 0x0C) { printf("expected kCodersUnpackSize\n"); return 1; }
          for (uint64_t i = 0; i < totOut; i++) unpackSize = ReadUVarint();
          // optional folder CRC
          while (g[pos] != 0x00) {
            Byte pid = g[pos++];
            if (pid == 0x0A) {
              Byte all = g[pos++];
              if (all) pos += 4 * numFolders;
              else { printf("crc bitmap unsupported\n"); return 1; }
            } else { printf("unknown unpackinfo id %02x\n", pid); return 1; }
          }
          pos++; // kEnd
        } else if (sid == 0x08) { // kSubStreamsInfo: skip generically
          // For 1 solid file: may contain kCRC. Parse: ids until kEnd, with kNumUnpackStream/kSize/kCRC.
          while (true) {
            Byte pid = g[pos++];
            if (pid == 0x00) break;
            if (pid == 0x0D) { ReadUVarint(); } // kNumUnpackStream (1 folder)
            else if (pid == 0x09) { ReadUVarint(); } // kSize (numSubstreams-1 = 0 entries) -- may not appear
            else if (pid == 0x0A) {
              Byte all = g[pos++];
              if (all) { /* count unknown; assume 1 crc */ pos += 4; }
              else { printf("crc bitmap unsupported\n"); return 1; }
            } else { printf("unknown substreaminfo id %02x\n", pid); return 1; }
          }
        } else { printf("unknown streamsinfo id %02x\n", sid); return 1; }
      }
    } else if (id == 0x05) { // kFilesInfo: skip rest
      break;
    } else { printf("unknown header id %02x\n", id); return 1; }
  }

  printf("packPos=%llu packSize=%llu unpackSize=%llu aesProps=%s\n",
         (unsigned long long)packPos, (unsigned long long)packSize,
         (unsigned long long)unpackSize,
         foundAes ? HexUpper(aesProps.data(), aesProps.size()).c_str() : "NONE");
  if (!foundAes) { printf("no 7zAES coder found\n"); return 1; }

  Byte key[32], iv[16];
  uint32_t cycles = 0;
  if (!SevenZipDeriveKey(aesProps.data(), aesProps.size(), argv[2], key, iv, &cycles)) {
    printf("derive failed\n"); return 1;
  }
  printf("NumCyclesPower=%u key=%s iv=%s\n", cycles, HexUpper(key, 32).c_str(), HexUpper(iv, 16).c_str());

  size_t encOff = 32 + packPos;
  if (encOff + packSize > g.size()) { printf("pack stream out of range\n"); return 1; }
  if (packSize % 16 != 0) { printf("packSize not multiple of 16\n"); return 1; }
  ByteBuf dec(packSize);
  Aes256CbcDecrypt(key, iv, g.data() + encOff, dec.data(), packSize);

  if (plain.size() > packSize || memcmp(dec.data(), plain.data(), plain.size()) != 0) {
    printf("DECRYPT MISMATCH\n");
    return 1;
  }
  printf("DECRYPT OK: first %zu bytes match the original file\n", plain.size());

  // wrong password must fail
  Byte key2[32], iv2[16];
  SevenZipDeriveKey(aesProps.data(), aesProps.size(), "WrongPass", key2, iv2, nullptr);
  ByteBuf dec2(packSize);
  Aes256CbcDecrypt(key2, iv2, g.data() + encOff, dec2.data(), packSize);
  printf("wrong-password decryption differs: %s\n",
         memcmp(dec2.data(), plain.data(), plain.size()) != 0 ? "yes (good)" : "NO (BAD)");
  return 0;
}

