// Brute-force 7zAES KDF variants against a real archive made by the reference binary.
#include "Aes.h"
#include "Hashes.h"
#include <cstdio>
#include <cstring>

static void DeriveVariant(int variant, const Byte* salt, size_t saltSize,
                          const std::string& password, uint32_t cycles, Byte key[32]) {
  ByteBuf pw;
  for (char c : password) { pw.push_back((Byte)c); pw.push_back(0); }
  ByteBuf base;
  base.insert(base.end(), salt, salt + saltSize);
  base.insert(base.end(), pw.begin(), pw.end());

  Hasher* sha = CreateSHA256();
  uint64_t rounds = (uint64_t)1 << cycles;
  for (uint64_t i = 0; i < rounds; i++) {
    sha->Update(base.data(), base.size());
    Byte ctr[8] = {0};
    uint64_t v = i;
    if (variant == 1 || variant == 3) v = i + 1;          // 1-based
    if (variant <= 1) { Set32(ctr, (uint32_t)v); sha->Update(ctr, 4); } // 4-byte LE
    else if (variant <= 3) { Set64(ctr, v); sha->Update(ctr, 8); }      // 8-byte LE
    else if (variant == 4) { for (int k = 0; k < 4; k++) ctr[k] = (Byte)(v >> (8*(3-k))); sha->Update(ctr, 4); } // 4-byte BE
  }
  sha->Final(key);
  delete sha;
}

int main() {
  // props/iv/packed data from the real archive (printed by previous run)
  const char* propsHex = "530F0A3977A776372EC04E30F9C0A99F8DF5";
  ByteBuf props(propsHex ? strlen(propsHex) / 2 : 0);
  for (size_t i = 0; i < props.size(); i++)
    sscanf(propsHex + 2 * i, "%2hhx", &props[i]);

  ByteBuf g;
  if (!ReadWholeFile("/tmp/enc_copy.7z", g)) return 1;
  ByteBuf plain;
  if (!ReadWholeFile("/tmp/plain.bin", plain)) return 1;
  uint64_t nextOff = Get64(g.data() + 12);
  // packPos was 0, packSize 1008, packed data starts right after signature header at 32
  size_t encOff = 32;
  size_t packSize = 1008;
  (void)nextOff;

  Byte iv[16];
  for (int variant = 0; variant <= 4; variant++) {
    Byte key[32];
    // parse props: salt=0, iv=16 at offset 2
    memset(iv, 0, 16);
    memcpy(iv, props.data() + 2, 16);
    DeriveVariant(variant, nullptr, 0, "MyPass123", 19, key);
    ByteBuf dec(packSize);
    Aes256CbcDecrypt(key, iv, g.data() + encOff, dec.data(), packSize);
    bool ok = memcmp(dec.data(), plain.data(), plain.size()) == 0;
    printf("variant %d (%s): %s  key=%s\n", variant,
           variant==0?"ctr32le,0-based":variant==1?"ctr32le,1-based":variant==2?"ctr64le,0-based":
           variant==3?"ctr64le,1-based":"ctr32be,0-based",
           ok ? "MATCH" : "no", HexUpper(key, 8).c_str());
    if (ok) return 0;
  }
  return 1;
}

